class Solution {
    public int maximumValue(String[] strs){
        int answer=0;
        for(String word:strs){
            boolean numeric=true;
            for(char character:word.toCharArray())if(!Character.isDigit(character)){
                numeric=false;
                break;
            }
            int value=numeric?Integer.parseInt(word):word.length();
            answer=Math.max(answer,value);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maximumValue(strs:Array<String>):Int{
        var answer=0;
        for(word in strs){
            val value=if(word.all{
                it.isDigit()
            })word.toInt()else word.length;
            answer=maxOf(answer,value)
        };
        return answer
    }
}

